const cats=['Shoes / Slippers','T-shirts','Fashion Clothing','Hoodies','Pants / Trousers','Leather Belts','Fashion Bags','Perfume','Electronics','Other Stuff'];
const descriptions=['Everyday sneakers, boots and laid-back slides.','Graphic prints, clean basics and everyday tees.','Layers, outerwear and pieces that finish the look.','Pullovers, zip-ups and relaxed matching sets.','Denim, cargos, shorts and everyday trousers.','Classic buckles and finishing touches.','Crossbody styles, shoulder bags and carry essentials.','Fragrance finds for your everyday rotation.','Audio, accessories and practical tech finds.','Small accessories and unexpected discoveries.'];
const icons=['◒','♧','◈','⌑','Ⅱ','∞','▱','♙','⌘','✳'];
const languages=[['en','English'],['de','Deutsch'],['fr','Français'],['es','Español'],['it','Italiano'],['pt','Português'],['nl','Nederlands'],['pl','Polski'],['sv','Svenska'],['da','Dansk'],['no','Norsk'],['fi','Suomi'],['cs','Čeština'],['ro','Română'],['hu','Magyar'],['el','Ελληνικά'],['tr','Türkçe'],['ru','Русский'],['uk','Українська'],['ar','العربية'],['ja','日本語'],['ko','한국어'],['zh-CN','简体中文'],['th','ไทย']];
const rates={USD:1,EUR:.92,GBP:.79,CAD:1.4,AUD:1.54,NZD:1.68,CHF:.88,SEK:10.6,NOK:10.9,DKK:6.87,PLN:3.98,CZK:23.3,HUF:375,RON:4.58,TRY:34,JPY:150,KRW:1400,CNY:7.25,HKD:7.78,SGD:1.35,THB:35,AED:3.67,SAR:3.75,INR:84,BRL:5.8,MXN:20};
let lang=localStorage.cssvipLang||'en',currency=localStorage.cssvipCurrency||'USD',catalog=[],dictionary={},productGallery=null,galleryIndex={},agents=[],guideData=null,mobileGuideData=null,limit=48;let gridColumns=['2','3','4'].includes(sessionStorage.gridColumns)?sessionStorage.gridColumns:'auto';const app=document.querySelector('#app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const t=s=>dictionary[lang]?.[s]||s;const tr=s=>`<span data-t="${esc(s)}">${esc(t(s))}</span>`;
const faqs=[["What can I do on CSSBuy VIP?",["Use this site to browse the product catalogue, search by product name or item ID, compare indicative prices and inspect available reference photos. Open a product’s internal detail page before choosing Buy on CSSBuy.","CSSBuy VIP is an independent discovery site. Account registration, purchasing, warehouse inspection, payments and parcel shipping take place on CSSBuy. Our use of the CSSBuy logo does not make this the official platform."]],["Where do the catalogue and categories come from?",["The catalogue is imported from kakobuymake.com across all ten categories and their listing pages. A category page lets you browse that category, change the sort order and choose the grid column count. The catalogue update date appears on the product detail page.","This is a catalogue snapshot, not a live stock feed. The same source item may appear in more than one category, and duplicate marketplace items can share a single detail page. Check the current CSSBuy listing for stock and final options."]],["How do I find a specific product or item ID?",["Open Spreadsheet and enter a product name, a useful keyword or the exact numeric item ID in Search. For example, 7909517519 opens the guide’s shorts example when that record is available. Use a category when you want to narrow the type of item.","If nothing matches, try a shorter English keyword or recheck the ID. A source website record number and a Weidian item ID are different identifiers. Confirm the picture, name and source ID on the detail page instead of choosing a result only because it looks similar."]],["How do I go from a find to a CSSBuy order?",["Click a product photo or name to open its CSSBuy VIP detail page. Review the item and reference photos, then select Buy on CSSBuy. Sign in, or use Join CSSBuy to register. On CSSBuy, choose the actual colour/style, size and quantity before reviewing the order.","Check the product ID and final charges before you personally submit and pay. Registration and purchase buttons contain referral parameters; some links may earn this site a commission. The detailed buying guide explains the separate product and international-shipping stages."]],["What does “Purchase link unavailable” mean?",["It means the source record does not currently contain a verified marketplace purchase ID/link that this site can safely use. A product may still have a title, price and reference photos, but those do not identify a valid CSSBuy purchase destination by themselves.","The purchase button is disabled for that record to avoid opening the wrong item. Do not replace its ID with a similar-looking product. Obtain the verified original item link from the source catalogue/store; once the record is corrected, it needs to be refreshed here before the button can work."]],["Does the displayed price include shipping and other charges?",["The displayed amount is an indicative item price from the source catalogue. It does not include international shipping or every charge that may apply. The current variant price, seller-to-warehouse delivery, payment fees and optional services should be checked on the CSSBuy order screen.","There are two separate payment stages: purchasing the item, then arranging international shipping after storage and QC. The later parcel quote depends on the goods, destination, packing and available route; any destination charges also need to be considered. Use the actual checkout amount, not a tutorial screenshot price."]],["How should I choose colour, size and quantity?",["Select the exact thumbnail or SKU on CSSBuy, then check that its label matches the version you want. Compare the seller’s size chart with your own measurements, including the stated units and whether a value is flat width or circumference. The guide’s selected size is only an example.","Confirm quantity, stock and minimum order quantity together. If you leave a purchase note, make it specific and consistent with the form selections. On smaller screens, scroll the options panel and verify all selected values before proceeding."]],["Are the QC photos from my order, and what should I check?",["No. QC reference photos on CSSBuy VIP show previously photographed source-catalogue items. They can help you examine visible details, but they are not photos of the new unit you order, a condition guarantee or authentication. Check the selected variant before comparing images.","Once your own item is stored, open its Warehouse record on CSSBuy and inspect the available photos. Compare colour, labels, quantity, seams, visible damage and any requested measurement. Ask for a specific missing view or measurement before including the item in an international parcel."]],["Why are some photos missing or different from the CSSBuy listing?",["Images depend on what the source catalogue supplied at the last import. Some records have no QC reference photos, an image may fail to load, and the seller may update its own listing after our snapshot. A cover image and a warehouse QC photo also serve different purposes.","Reload once if an image does not appear, then compare the exact item ID and variant on CSSBuy. A missing photo does not prove the item is out of stock or has passed inspection. If you cannot verify an important detail, resolve it through the source listing or CSSBuy before paying or shipping."]],["Where do I track orders, shipping or a return request?",["CSSBuy handles these records. Use your CSSBuy account for purchase progress, warehouse inspection and My Parcel for international tracking. The current account menu is the reference for available actions.","For a wrong, damaged or unwanted item, open the matching record and check its current support/return conditions and deadline. Keep the order or parcel number and relevant photos. CSSBuy VIP cannot cancel platform orders, approve returns or issue refunds; contact CSSBuy through the corresponding record."]],["How do the language and currency controls work?",["The header has separate language and currency menus. Languages use their complete native names, and currency changes convert the displayed catalogue reference amount. On smaller screens, open the menu to access these controls. Your selections are retained when you browse this site.","Currency conversion here is indicative; it does not set CSSBuy’s settlement currency, exchange rate or payment-provider fee. Content translation coverage also varies: the detailed guide and this rewritten FAQ are currently available in English and Simplified Chinese, while other language content is still being completed."]],["What do the buying guide illustrations show?",["The guide uses historical desktop screenshots from CSSBuy’s own public Buy For Me instructions. These explain the sequence from selecting an item to paying for international delivery. Current controls, quotes and route availability may differ from the examples.","Computer and Phone controls let you select the instruction view. Verified phone-specific parcel screenshots are still being prepared and are labelled accordingly. A historical desktop example remains labelled as a desktop image when you open it on a phone."]]];
function money(p){if(!(p>0))return t('Check current price');return new Intl.NumberFormat(lang,{style:'currency',currency}).format(p*rates[currency])}
function translate(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.querySelector('#langBtn .picker-label').textContent=languages.find(([code])=>code===lang)?.[1]||'English';updatePickerSelection()}
function agentUrl(agent,id){if(agent.status!=='active'||!/^\d{9,12}$/.test(id))return null;return agent.template.replaceAll('{id}',encodeURIComponent(id)).replaceAll('{url}',encodeURIComponent('https://weidian.com/item.html?itemID='+id))}
function renderOtherAgents(p){
 if(!agents.length||p.purchaseUnavailable)return '';
 const ordered=[...agents].sort((a,b)=>(b.id==='cssbuy')-(a.id==='cssbuy'));
 return `<div class="agent-options"><button class="agents-trigger" type="button" aria-haspopup="dialog" aria-controls="agent-dialog">${tr('Other purchasing agents')}<span class="agent-trigger-icons" aria-hidden="true">${ordered.filter(a=>a.id!=='cssbuy').slice(0,4).map(a=>`<img src="${esc(a.icon)}" alt="" width="22" height="22">`).join('')}</span></button></div><dialog class="agent-dialog" id="agent-dialog" aria-labelledby="agent-dialog-title" aria-describedby="agent-dialog-description"><div class="agent-dialog-heading"><h2 id="agent-dialog-title">${tr('Other purchasing agents')}</h2><button class="agent-close" type="button" aria-label="${esc(t('Close'))}">×</button></div><p id="agent-dialog-description">${tr('Open this same item with your preferred agent. Each platform calculates its own final price and shipping.')}</p><input class="agent-search" type="search" placeholder="${esc(t('Search purchasing agents'))}" aria-label="${esc(t('Search purchasing agents'))}" autocomplete="off"><div class="agent-list">${ordered.map(a=>{
  const href=agentUrl(a,p.id),current=a.id==='cssbuy';


  const inner=`<img src="${esc(a.icon)}" alt="" width="40" height="40"><span class="agent-name"><strong>${esc(a.name)}</strong>${current?`<small>${esc(t('Current platform'))}</small>`:!href?`<small>${esc(t('Purchase link unavailable'))}</small>`:''}</span>${href?`<span class="agent-open">${esc(t('Open'))}</span>`:''}`;
  return `<div class="agent-row ${current?'is-current':''}" data-agent-name="${esc(a.name.toLowerCase())}">${href?`<a class="agent-link" data-agent="${esc(a.id)}" href="${esc(href)}" target="_blank" rel="sponsored noopener noreferrer" aria-label="${esc(t('Buy on')+' '+a.name)}">${inner}</a>`:`<button class="agent-link" data-agent="${esc(a.id)}" type="button" disabled>${inner}</button>`}<button class="agent-copy" type="button" ${href?`data-copy-agent="${esc(href)}" aria-label="${esc(t('Copy link')+' · '+a.name)}"`:'disabled'}>${esc(t('Copy link'))}</button></div>`;
 }).join('')}<p class="agent-empty" hidden>${tr('No matching platforms')}</p></div><p class="agent-copy-status" role="status" aria-live="polite"></p><input class="agent-copy-fallback" readonly hidden aria-label="${esc(t('Select and copy this link'))}"></dialog>`;
}
function bindOtherAgents(){
 const dialog=document.querySelector('#agent-dialog'),trigger=document.querySelector('.agents-trigger');if(!dialog||!trigger)return;
 trigger.onclick=()=>{dialog.querySelector('.agent-search').value='';dialog.querySelectorAll('.agent-row').forEach(row=>row.hidden=false);dialog.querySelector('.agent-empty').hidden=true;dialog.querySelector('.agent-copy-status').textContent='';dialog.querySelector('.agent-copy-fallback').hidden=true;dialog.showModal();document.body.classList.add('agents-modal-open')};
 dialog.querySelector('.agent-close').onclick=()=>dialog.close();
 dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dialog.close()}});
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 dialog.addEventListener('close',()=>document.body.classList.remove('agents-modal-open'));
 dialog.querySelector('.agent-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();let visible=0;dialog.querySelectorAll('.agent-row').forEach(row=>{row.hidden=!row.dataset.agentName.includes(q);if(!row.hidden)visible++});dialog.querySelector('.agent-empty').hidden=visible>0};
 dialog.querySelectorAll('[data-copy-agent]').forEach(button=>button.onclick=async()=>{try{await navigator.clipboard.writeText(button.dataset.copyAgent);button.textContent=t('Copied');dialog.querySelector('.agent-copy-status').textContent=t('Link copied');setTimeout(()=>{if(button.isConnected)button.textContent=t('Copy link')},1800)}catch{const field=dialog.querySelector('.agent-copy-fallback');field.hidden=false;field.value=button.dataset.copyAgent;field.focus();field.select();dialog.querySelector('.agent-copy-status').textContent=t('Select and copy this link')}});
}
function galleryPhotos(p){
 const g=productGallery?.id===p.id?productGallery:null,photos=[];
 for(const [i,url] of (g?.carousel||[]).entries())photos.push({image:url,label:t('Product photo')+' '+(i+1)});
 for(const style of g?.styles||[])if(!photos.some(x=>x.image===style.image))photos.push({image:style.image,label:style.label});
 return photos.length?photos:[{image:p.image,label:t('Catalogue cover')}];
}
function thumbnailUrl(image){const url=new URL(image);if(url.hostname.endsWith('.geilicdn.com')){url.searchParams.set('w','180');url.searchParams.set('h','180');url.searchParams.set('cp','0')}return url.href}
function galleryThumbnail(image,label,selected){return `<button class="gallery-thumb" type="button" data-photo-src="${esc(image)}" data-photo-label="${esc(label)}" aria-label="${esc(t('View photo')+' · '+label)}" title="${esc(label)}" aria-pressed="${image===selected}"><img referrerpolicy="no-referrer" src="${esc(thumbnailUrl(image))}" data-original-src="${esc(image)}" alt="${esc(label)}" loading="lazy"></button>`}
function renderProductGallery(p){
 const g=productGallery?.id===p.id?productGallery:null,first=galleryPhotos(p)[0];
 return `<div class="product-gallery"><button class="gallery-main" type="button" aria-label="${esc(t('Enlarge product photo'))}" aria-keyshortcuts="ArrowLeft ArrowRight"><img referrerpolicy="no-referrer" class="cover" id="gallery-main-image" src="${esc(first.image)}" alt="${esc(p.name+' · '+first.label)}"></button><span class="visually-hidden" id="gallery-photo-caption" role="status">${esc(first.label)}</span>${g?.carousel?.length?`<div class="gallery-strip" aria-label="${esc(t('Product photos'))}">${g.carousel.map((url,i)=>galleryThumbnail(url,t('Product photo')+' '+(i+1),first.image)).join('')}</div>`:''}<dialog class="gallery-lightbox" aria-label="${esc(t('Product photo'))}"><button type="button" class="gallery-close" aria-label="${esc(t('Close'))}">×</button><img referrerpolicy="no-referrer" referrerpolicy="no-referrer" alt="${esc(p.name)}"><p class="visually-hidden"></p></dialog></div>`;
}
function renderProductStyles(p){
 const g=productGallery?.id===p.id?productGallery:null,first=galleryPhotos(p)[0];
 if(!g?.styles?.length)return `<div class="gallery-styles gallery-pending"><p class="gallery-note">${tr(g?.status==='available'||g?.status==='no_images'?'The source does not currently provide separate style photos for this item.':'Style photos have not been imported for this item yet.')}</p></div>`;
 return `<section class="gallery-styles" aria-labelledby="product-styles-title"><h2 id="product-styles-title">${tr('Styles & colours')} <span class="style-count">${g.styles.length}</span></h2><div class="style-grid">${g.styles.map(x=>galleryThumbnail(x.image,x.label,first.image)).join('')}</div></section>`;
}
function bindProductGallery(){
 const container=document.querySelector('.detail');if(!container?.querySelector('.product-gallery'))return;
 const p=catalog.find(p=>p.id===location.pathname.split('/')[2]||p.legacyIds?.includes(location.pathname.split('/')[2]));if(!p)return;
 const photos=galleryPhotos(p),main=container.querySelector('#gallery-main-image'),caption=container.querySelector('#gallery-photo-caption'),box=container.querySelector('.gallery-lightbox');let selected=0;
 const select=(src,label)=>{selected=Math.max(0,photos.findIndex(x=>x.image===src));main.src=src;main.alt=p.name+' · '+label;caption.textContent=label;container.querySelectorAll('[data-photo-src]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.photoSrc===src)))};
 container.querySelectorAll('[data-photo-src]').forEach(b=>b.onclick=()=>select(b.dataset.photoSrc,b.dataset.photoLabel));
 container.querySelector('.gallery-main').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const next=photos[(selected+(e.key==='ArrowRight'?1:-1)+photos.length)%photos.length];select(next.image,next.label)}};
 container.querySelector('.gallery-main').onclick=()=>{box.querySelector('img').src=main.src;box.querySelector('img').alt=main.alt;box.querySelector('p').textContent=caption.textContent;box.showModal();document.body.classList.add('gallery-modal-open')};
 box.querySelector('.gallery-close').onclick=()=>box.close();box.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();box.close()}});box.addEventListener('close',()=>document.body.classList.remove('gallery-modal-open'));box.addEventListener('click',e=>{if(e.target===box)box.close()});
}
function card(p){return `<a class="card" href="/product/${p.id}/"><div class="photo"><img loading="lazy" referrerpolicy="no-referrer" src="${p.image}" alt="${esc(p.name)}">${p.qc.length?'<span class="tag">QC</span>':''}</div><div class="meta"><span>${esc(t(cats[p.cat]))}</span></div><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}${p.price>0?`<small>${esc(t('item price'))}</small>`:''}</div></a>`}
function search(){return `<form class="search" action="/spreadsheet/"><span>${svg('search')}</span><input aria-label="Search products" name="q" placeholder="${esc(t('Search sneakers, hoodies, bags…'))}" value="${esc(new URLSearchParams(location.search).get('q')||'')}"><a class="photo-search" href="/image-search/" aria-label="${esc(t('Search by photo'))}" title="${esc(t('Search by photo'))}">${svg('camera')}</a><button>${esc(t('Search'))}</button></form>`}
function strip(active=-1){return `<div class="category-strip">${cats.map((c,i)=>`<a class="pill ${active===i?'active':''}" href="/category/${i}/">${esc(t(c))}</a>`).join('')}</div>`}
function faq(){return `<section class="faq" id="faq" aria-labelledby="faq-title"><div class="faq-heading"><div><div class="eyebrow">${tr('GOOD TO KNOW')}</div><h2 id="faq-title">${tr('CSSBuy VIP FAQ')}</h2></div><p>${tr('12 useful answers. Select a question to read more.')}</p></div><div class="faq-grid">${[faqs.slice(0,6),faqs.slice(6)].map(group=>`<div class="faq-column">${group.map(([q,answers])=>`<details class="question"><summary><h3>${tr(q)}</h3><span class="faq-chevron" aria-hidden="true"></span></summary><div class="faq-answer">${answers.map(a=>`<p>${tr(a)}</p>`).join('')}</div></details>`).join('')}</div>`).join('')}</div></section>`}
function renderBase(){let path=location.pathname,query=new URLSearchParams(location.search);let cat=path.startsWith('/category/')?Number(path.split('/')[2]):-1;let q=query.get('q')||'';let searchTerm=q.trim();try{const u=new URL(searchTerm);searchTerm=u.searchParams.get('itemID')||u.searchParams.get('goodsId')||searchTerm}catch{}
if(path.startsWith('/image-search')){app.innerHTML=`<div class="hero"><div class="eyebrow">${tr('PHOTO SEARCH')}</div><h1>${tr('Search by photo')}</h1><p>${tr('Visual matching is being prepared. You can still search the catalogue by keyword or item ID.')}</p>${search()}</div><div class="search-unavailable"><h2>${tr('Image matching is not available yet.')}</h2><p>${tr('Use a product name or the original Weidian item ID to find the correct listing.')}</p><a class="textlink" href="/spreadsheet/">${tr('Browse the spreadsheet')}</a></div>`}
else if(path.startsWith('/product/')){let p=catalog.find(p=>p.id===path.split('/')[2]||p.legacyIds?.includes(path.split('/')[2]));if(!p){app.innerHTML=`<div class="empty">${tr('Product not found')}<p><a href="/spreadsheet/">${tr('Browse the spreadsheet')}</a></p></div>`;return}document.title=p.name+' | CSSBuy VIP';app.innerHTML=`<div class="breadcrumb"><a href="/">${tr('Home')}</a> / <a href="/category/${p.cat}/">${esc(t(cats[p.cat]))}</a> / ${p.id}</div><section class="detail">${renderProductGallery(p)}<div class="product-info"><div class="eyebrow">${esc(t(cats[p.cat]))}</div><h1>${esc(p.name)}</h1><div class="price">${money(p.price)}</div><p>${tr('Reference item price. Shipping and additional fees are calculated by CSSBuy.')}</p>${p.purchaseUnavailable?`<button class="primary" disabled>${tr('Purchase link unavailable')}</button><p>${tr('The source catalogue does not provide a verified purchase link for this item.')}</p>`:`<a class="primary" href="https://www.cssbuy.com/item-micro-${p.id}.html?promotionCode=b949d0d72e6d7314" target="_blank" rel="sponsored noopener"><img class="primary-agent-icon" src="/favicon.png" alt="" width="24" height="24">${tr('Buy on CSSBuy')}</a>`}${renderOtherAgents(p)}${renderProductStyles(p)}<div class="facts">${tr('Source')}: ${p.purchaseUnavailable?'Main catalogue · '+p.aid:'Weidian · '+p.id}<br>${tr('Currency conversions are indicative. Confirm the final price before paying.')}<br>${tr('Catalogue updated')}: 2026-11-26</div><p>${tr('Review the photos below, then check your own warehouse QC before shipping.')}</p></div></section><section><div class="sectionhead"><div><h2>${tr('QC reference photos')}</h2><p>${tr('Historical reference images from the source catalogue; your item may vary.')}</p></div></div><div class="qc-grid">${!p.qc.length?`<p>${tr('No QC reference photos are available in the source catalogue for this item.')}</p>`:p.qc.map(src=>`<a href="${src}" target="_blank" rel="noopener"><img loading="lazy" referrerpolicy="no-referrer" src="${src}" alt="${esc(p.name)} QC reference"></a>`).join('')}</div></section>`}
else if(path.startsWith('/guide')){app.innerHTML=renderPracticalGuide();bindGuideDevice();if(location.hash.startsWith('#step-'))requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({block:'start'}));document.querySelectorAll('[data-copy-guide]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copyGuide);b.textContent=lang==='zh-CN'?'已复制':'Copied'}catch{b.textContent=lang==='zh-CN'?'请选中文字复制':'Select text to copy'}})}
else if(path.startsWith('/categories')){app.innerHTML=`<div class="hero"><div class="eyebrow">${tr('FIND YOUR ROTATION')}</div><h1>${tr('Browse categories')}</h1><p>${tr('Ten categories. A more focused way to find your next piece.')}</p></div><section class="category-grid">${cats.map((c,i)=>`<a class="category-card" href="/category/${i}/"><span>${icons[i]}</span><div><h3>${esc(t(c))}</h3><p>${esc(t(descriptions[i]))}</p></div></a>`).join('')}</section>`}
else{let home=path==='/'&&!q;let rows=catalog.filter(p=>(cat<0||p.cat===cat||p.sourceCategories?.includes(cat))&&(!q||[p.name,p.id,p.sourceName||''].join(' ').toLowerCase().includes(searchTerm.toLowerCase())));let sort=query.get('sort')||'new';if(sort==='low')rows.sort((a,b)=>(a.price>0?a.price:Infinity)-(b.price>0?b.price:Infinity));if(sort==='high')rows.sort((a,b)=>(b.price>0?b.price:-Infinity)-(a.price>0?a.price:-Infinity));if(sort==='az')rows.sort((a,b)=>a.name.localeCompare(b.name));let selected=home?feature(rows):rows.slice(0,limit);app.innerHTML=`<div class="hero"><div class="eyebrow">${tr(home?'YOUR NEXT FIND STARTS HERE':'THE FINDS DIRECTORY')}</div><h1>${home?'CSSBuy <em>Spreadsheet.</em>':esc(t(cat>=0?cats[cat]:'The spreadsheet.'))}</h1><p>${tr(home?'Good finds. Less searching. Explore a considered edit of sneakers, clothing and everyday essentials — with prices and QC references in one place.':cat>=0?descriptions[cat]:'Explore the catalogue. Find a piece, check the details and open it on CSSBuy.')}</p>${search()}<div class="hint">${tr('Independent picks · Reference prices · Direct CSSBuy links')}</div></div>${strip(cat)}<section><div class="sectionhead"><div><h2>${tr(home?'On the desk today':q?'Search results':'Explore the finds')}</h2><p>${home?tr('A fresh edit for your next rotation.'):`${rows.length} ${esc(t(rows.length===1?'product':'products'))}${q?' · '+esc(q):''}`}</p></div>${home?`<a class="textlink" href="/spreadsheet/">${tr('View spreadsheet')}</a>`:`<div class="toolbar"><select id="sort" aria-label="Sort products"><option value="new">${esc(t('Newest first'))}</option><option value="low">${esc(t('Price: low to high'))}</option><option value="high">${esc(t('Price: high to low'))}</option><option value="az">A–Z</option></select><select id="columns" aria-label="Grid columns"><option value="auto">${esc(t('Automatic'))}</option><option value="4">4 ${esc(t('columns'))}</option><option value="3">3 ${esc(t('columns'))}</option><option value="2">2 ${esc(t('columns'))}</option></select></div>`}</div><div class="grid">${selected.map(card).join('')}</div>${!rows.length?`<div class="empty">${tr('No matching products. Try another search.')}</div>`:''}${!home&&rows.length>limit?`<button class="load" id="load">${esc(t('Show more'))}</button>`:''}</section>${home?`<div class="desk-note"><div><div class="eyebrow">${tr('FROM FIND TO FRONT DOOR')}</div><h2>${tr('A good find deserves a closer look.')}</h2><p>${tr('Start with the details. Compare reference photos, check the price and make your final choices on CSSBuy.')}</p><a class="textlink" href="/guide/">${tr('Read the first-order guide')}</a></div><div class="steps">${[['Find your piece','Browse the spreadsheet or explore a category.'],['Check the details','Use reference photos to take a closer look.'],['Make it yours','Confirm options and checkout on CSSBuy.']].map(([h,p])=>`<div class="step"><strong>${tr(h)}</strong><p>${tr(p)}</p></div>`).join('')}</div></div>${faq()}`:''}`;if(!home){document.querySelector('#sort').value=sort;document.querySelector('#sort').onchange=e=>{query.set('sort',e.target.value);location.search=query};document.querySelector('#columns').value=gridColumns;document.querySelector('.grid').style.gridTemplateColumns=gridColumns==='auto'?'':`repeat(${gridColumns},minmax(0,1fr))`;document.querySelector('#columns').onchange=e=>{gridColumns=e.target.value;sessionStorage.gridColumns=gridColumns;document.querySelector('.grid').style.gridTemplateColumns=gridColumns==='auto'?'':`repeat(${gridColumns},minmax(0,1fr))`};document.querySelector('#load')?.addEventListener('click',()=>{let y=scrollY;limit+=48;render();scrollTo(0,y)})}}
bindProductGallery();bindOtherAgents();translate();if(location.hash==='#faq')requestAnimationFrame(()=>document.getElementById('faq')?.scrollIntoView({block:'start'}))}
function render(){
 document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='/'?location.pathname==='/':location.pathname.startsWith(a.getAttribute('href'))));
 if(location.pathname==='/'&&!location.search){app.innerHTML=renderVIPHome();translate();balanceCategoryRows();if(location.hash==='#faq')requestAnimationFrame(()=>document.getElementById('faq')?.scrollIntoView({block:'start'}));return}
 renderBase();
}
const guideDeviceMedia=window.matchMedia('(max-width: 768px)');
let guideDeviceChoice=['auto','desktop','mobile'].includes(sessionStorage.guideDevice)?sessionStorage.guideDevice:'auto';
function guideDevice(){return guideDeviceChoice==='auto'?(guideDeviceMedia.matches?'mobile':'desktop'):guideDeviceChoice}
guideDeviceMedia.addEventListener('change',()=>{if(guideDeviceChoice==='auto'&&location.pathname.startsWith('/guide'))render()});
function bindGuideDevice(){document.querySelectorAll('[data-guide-device]').forEach(b=>b.onclick=()=>{guideDeviceChoice=b.dataset.guideDevice;sessionStorage.guideDevice=guideDeviceChoice;render()})}
function renderPracticalGuide(){return renderCSSGuide()}
function feature(rows){const picks=[];for(let c of [0,3,2,6,4,1,0,3,6,4,0,2]){let p=rows.find(p=>p.cat===c&&!picks.includes(p));if(p)picks.push(p)}for(let p of rows)if(picks.length<12&&!picks.includes(p))picks.push(p);return picks}
const symbols={USD:'$',EUR:'€',GBP:'£',CAD:'C$',AUD:'A$',NZD:'NZ$',CHF:'Fr',SEK:'kr',NOK:'kr',DKK:'kr',PLN:'zł',CZK:'Kč',HUF:'Ft',RON:'lei',TRY:'₺',JPY:'¥',KRW:'₩',CNY:'¥',HKD:'HK$',SGD:'S$',THB:'฿',AED:'د.إ',SAR:'﷼',INR:'₹',BRL:'R$',MXN:'MX$'};
const panels=['languages','currencies'];
function closePickers(){panels.forEach(id=>{document.getElementById(id).hidden=true;document.querySelector('[aria-controls="'+id+'"]').setAttribute('aria-expanded','false')})}
function togglePicker(id){const wasOpen=!document.getElementById(id).hidden;closePickers();if(!wasOpen){document.querySelector('header').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');document.getElementById(id).hidden=false;document.querySelector('[aria-controls="'+id+'"]').setAttribute('aria-expanded','true')}}
function updatePickerSelection(){document.querySelectorAll('[data-code]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.code===lang));b.classList.toggle('selected',b.dataset.code===lang)});document.querySelectorAll('[data-currency]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.currency===currency));b.classList.toggle('selected',b.dataset.currency===currency)});document.querySelector('#currencyBtn .picker-label').textContent=currency+' '+symbols[currency]}
document.querySelector('#languages .picker-options').innerHTML=languages.map(([code,label])=>`<button type="button" data-code="${code}" lang="${code}">${label}</button>`).join('');
document.querySelector('#currencies .picker-options').innerHTML=Object.keys(rates).map(code=>`<button type="button" data-currency="${code}" aria-label="${code}"><span>${code}</span><span class="currency-symbol">${symbols[code]}</span></button>`).join('');
document.querySelector('#langBtn').onclick=()=>togglePicker('languages');document.querySelector('#currencyBtn').onclick=()=>togglePicker('currencies');
document.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>{lang=b.dataset.code;localStorage.cssvipLang=lang;closePickers();render();document.querySelector('#langBtn').focus()});
document.querySelectorAll('[data-currency]').forEach(b=>b.onclick=()=>{currency=b.dataset.currency;localStorage.cssvipCurrency=currency;closePickers();render();document.querySelector('#currencyBtn').focus()});
document.querySelector('#menu').onclick=()=>{const open=document.querySelector('header').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open));closePickers()};
document.addEventListener('click',e=>{if(!e.target.closest('.picker'))closePickers()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=panels.find(id=>!document.getElementById(id).hidden);closePickers();if(open)document.querySelector('[aria-controls="'+open+'"]').focus()}if(e.key==='ArrowDown'&&e.target.matches('.picker-trigger')){e.preventDefault();const id=e.target.getAttribute('aria-controls');if(document.getElementById(id).hidden)togglePicker(id);document.querySelector('#'+id+' button').focus()}});
Promise.all([location.pathname.startsWith('/guide')?Promise.resolve([]):fetch('/catalog.json',{cache:'no-store'}).then(r=>r.json()),fetch('/translations.json',{cache:'no-store'}).then(r=>r.json()).catch(()=>({})),fetch('/guide.json',{cache:'no-store'}).then(r=>r.json()).catch(()=>null),fetch('/guide-mobile.json',{cache:'no-store'}).then(r=>r.json()).catch(()=>null),fetch('/platforms.json',{cache:'no-store'}).then(r=>r.json()).catch(()=>[]),fetch('/gallery-index.json',{cache:'no-store'}).then(r=>r.json()).catch(()=>({}))]).then(async([c,d,g,m,a,gi])=>{galleryIndex=gi;catalog=c;dictionary=d;guideData=g;mobileGuideData=m;agents=a;if(location.pathname.startsWith('/product/')){const id=location.pathname.split('/')[2],p=catalog.find(p=>p.id===id||p.legacyIds?.includes(id));if(p&&['available','no_images'].includes(galleryIndex[p.id]?.status))try{const response=await fetch('/data/galleries/'+encodeURIComponent(p.id)+'.json',{cache:'no-store'});if(response.ok)productGallery=await response.json()}catch{productGallery=null}}render()}).catch(()=>app.innerHTML='<div class="empty">The catalogue is unavailable. Please reload this page.</div>');
